mapper.select:
SELECT ol.id, ol.user_id AS userId, u.name AS userName, ol.operation, ol.target_type AS targetType, ol.target_id AS targetId, ol.ip, ol.user_agent AS userAgent, ol.created_at AS createdAt FROM operation_log ol LEFT JOIN user u ON ol.user_id = u.id
AND ol.user_id = #{userId}
AND u.name LIKE CONCAT('%', #{userName}, '%')
AND ol.operation LIKE CONCAT('%', #{operation}, '%')
AND ol.created_at >= #{startTime}
AND ol.created_at <= #{endTime}
ORDER BY ol.created_at DESC

